#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <cassert>
#include <iostream>
enum class Phase{Tell,Active,Recovery};
class Attack{
    int tick_=0;
    bool hit_=false;
public:
    Phase phase()const{return tick_<2?Phase::Tell:(tick_==2?Phase::Active:Phase::Recovery);}
    bool tryHit(bool overlaps){
        if(phase()!=Phase::Active || !overlaps || hit_)return false;
        hit_=true;return true;
    }
    void advance(){if(++tick_==5){tick_=0;hit_=false;}}
};
int main(){
    Attack a;assert(a.phase()==Phase::Tell && !a.tryHit(true));
    a.advance();assert(a.phase()==Phase::Tell);
    a.advance();assert(a.phase()==Phase::Active);
    assert(!a.tryHit(false));assert(a.tryHit(true));assert(!a.tryHit(true));
    a.advance();assert(a.phase()==Phase::Recovery && !a.tryHit(true));
    a.advance();assert(a.phase()==Phase::Recovery);
    a.advance();assert(a.phase()==Phase::Tell);
    a.advance();a.advance();assert(a.tryHit(true));
    std::cout<<"action window tests passed\n";
}
